// Per-kind dispatch: f(table of that kind). Used by the EntityStore, the only reader of these tables.
template <class Tables, class F>
void dispatch(EntityKind kind, Tables& t, F&& f) {
  switch (kind) {
    case EntityKind::agent: f(t.agent); return;
    case EntityKind::animal: f(t.animal); return;
    case EntityKind::plant: f(t.plant); return;
    case EntityKind::item: f(t.item); return;
    case EntityKind::structure: f(t.structure); return;
    case EntityKind::terrain: f(t.terrain); return;
    case EntityKind::water_body: f(t.water_body); return;
    case EntityKind::fire: f(t.fire); return;
    case EntityKind::phenomenon: f(t.phenomenon); return;
    case EntityKind::place: f(t.place); return;
    case EntityKind::world: f(t.world); return;
    case EntityKind::trace: f(t.trace); return;
    case EntityKind::fact: f(t.fact); return;
    case EntityKind::group: f(t.group); return;
    case EntityKind::role: f(t.role); return;
    case EntityKind::agreement: f(t.agreement); return;
    default: return;
  }
}

// Tables of the store: one dense row vector per kind (the template is KindTable in entity_store.h).
template <template <class> class Table>
struct Tables {
  Table<AgentData> agent;
  Table<AnimalData> animal;
  Table<PlantData> plant;
  Table<ItemData> item;
  Table<StructureData> structure;
  Table<TerrainData> terrain;
  Table<WaterBodyData> water_body;
  Table<FireData> fire;
  Table<PhenomenonData> phenomenon;
  Table<PlaceData> place;
  Table<WorldData> world;
  Table<TraceData> trace;
  Table<FactData> fact;
  Table<GroupData> group;
  Table<RoleData> role;
  Table<AgreementData> agreement;
};

